tool_use_result.stdout:
/* Shared components: header, button, card, form, table, modal, and friends. */

/* Header */

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-line);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--header-height);
}

.brand {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 18px;
  font-weight: 800;
  color: var(--color-ink);
  text-decoration: none;
}

.site-nav {
  display: flex;
  gap: var(--space-1);
}

.nav-link {
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 600;
  color: var(--color-ink);
  text-decoration: none;
}

.nav-link:hover {
  background: var(--color-bg);
}

.nav-link[aria-current='page'] {
  color: var(--color-brand);
  background: var(--color-brand-tint);
}

.nav-toggle {
  display: none;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  cursor: pointer;
}

.nav-toggle-bar {
  display: block;
  width: 18px;
  height: 2px;
  margin: 4px auto;
  border-radius: 1px;
  background: var(--color-ink);
}

/* Button */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 18px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  font: inherit;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.2;
  text-decoration: none;
  cursor: pointer;
}

.btn-primary {
  background: var(--color-brand);
  color: #ffffff;
}

.btn-primary:hover {
  background: var(--color-brand-dark);
}

.btn-secondary {
  background: var(--color-surface);
  color: var(--color-ink);
  border-color: var(--color-line);
}

.btn-secondary:hover {
  background: var(--color-bg);
}

.btn-sm {
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 13px;
}

.btn-lg {
  padding: 13px 24px;
  font-size: 16px;
}

.btn[disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Card */

.card {
  position: relative;
  overflow: hidden;
  background: var(--color-surface);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}

.card-body {
  padding: var(--space-5);
}

.card-thumb {
  height: 120px;
  border-radius: 13px 13px 0 0;
}

.card h3 {
  margin-bottom: var(--space-2);
}

.card p {
  font-size: 15px;
  color: var(--color-muted);
}

.card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: var(--space-4);
}

.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-5);
}

.cards-4 {
  grid-template-columns: repeat(4, 1fr);
}

.badge {
  position: absolute;
  top: -10px;
  right: -10px;
  padding: 3px 10px;
  border-radius: var(--radius-pill);
  background: var(--color-brand);
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
}

.badge-sale {
  background: var(--color-danger);
}

.price {
  font-size: 20px;
  font-weight: 800;
  color: var(--color-brand);
}

/* Stat */

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.stat {
  padding: var(--space-4) var(--space-5);
  background: var(--color-surface);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
}

.stat-value {
  font-size: 28px;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.stat-label {
  font-size: 14px;
  color: var(--color-muted);
}

/* Form */

.form .btn {
  min-width: 140px;
}

.form-field {
  margin-bottom: var(--space-4);
}

.form-label {
  display: block;
  margin-bottom: var(--space-1);
  font-size: 14px;
  font-weight: 600;
}

.form-input {
  display: block;
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-md);
  background: var(--color-surface);
  font: inherit;
  font-size: 15px;
  color: var(--color-ink);
}

textarea.form-input {
  min-height: 120px;
  resize: vertical;
}

.form-input:focus {
  outline: 2px solid var(--color-brand);
  outline-offset: 1px;
}

.form-input.is-invalid {
  border-color: var(--color-danger);
}

.form-error {
  margin-top: var(--space-1);
  font-size: 13px;
  color: var(--color-danger);
}

.form-check {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  font-size: 14px;
}

.form-check input {
  margin: 3px 0 0;
}

.form-inline {
  display: flex;
  gap: var(--space-2);
}

.form-inline .form-input {
  flex: 1;
  min-width: 0;
}

/* Table */

.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  background: var(--color-surface);
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: 15px;
}

.table th,
.table td {
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--color-line);
  text-align: left;
  white-space: nowrap;
}

.table th {
  background: var(--color-bg);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--color-muted);
}

.table tbody tr:last-child td {
  border-bottom: 0;
}

.table .num {
  text-align: right;
}

/* Pill */

.pill {
  display: inline-block;
  padding: 2px 10px;
  border-radius: var(--radius-pill);
  font-size: 13px;
  font-weight: 600;
}

.pill-ok {
  background: var(--color-success-tint);
  color: var(--color-success);
}

.pill-warn {
  background: var(--color-warning-tint);
  color: var(--color-warning);
}

.pill-err {
  background: var(--color-danger-tint);
  color: var(--color-danger);
}

/* Alert */

.alert {
  padding: var(--space-3) var(--space-4);
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  font-size: 15px;
}

.alert-ok {
  background: var(--color-success-tint);
  border-color: #b7e2c6;
  color: var(--color-success);
}

/* Modal */

.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4);
  background: rgba(31, 35, 40, 0.5);
}

.modal-dialog {
  width: 100%;
  max-width: 480px;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) var(--space-5);
  border-bottom: 1px solid var(--color-line);
}

.modal-close {
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  font: inherit;
  font-size: 22px;
  line-height: 1;
  color: var(--color-muted);
  cursor: pointer;
}

.modal-body {
  padding: var(--space-5);
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-2);
  padding: var(--space-4) var(--space-5);
  border-top: 1px solid var(--color-line);
}

.detail-list {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: var(--space-2) var(--space-4);
}

.detail-list dt {
  font-size: 14px;
  color: var(--color-muted);
}

.detail-list dd {
  font-weight: 600;
}

/* Footer */

.site-footer {
  margin-top: var(--space-8);
  padding: var(--space-5) 0;
  border-top: 1px solid var(--color-line);
  font-size: 14px;
  color: var(--color-muted);
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
}

.footer-links {
  display: flex;
  gap: var(--space-4);
}

.footer-links a {
  color: var(--color-muted);
}

@media (max-width: 720px) {
  .nav-toggle {
    display: block;
  }

  .site-nav {
    display: none;
    position: absolute;
    top: var(--header-height);
    right: 0;
    left: 0;
    flex-direction: column;
    gap: 0;
    padding: var(--space-2) var(--space-4) var(--space-4);
    background: var(--color-surface);
    border-bottom: 1px solid var(--color-line);
    box-shadow: var(--shadow-md);
  }

  .site-nav.is-open {
    display: flex;
  }

  .nav-link {
    padding: var(--space-3);
  }

  .cards,
  .cards-4,
  .stats {
    grid-template-columns: 1fr;
  }

  .footer-inner {
    flex-direction: column;
    align-items: flex-start;
  }
}

content.content:
/* Page sections. Each block is used by the page named in its comment. */

/* Home */

.hero {
  position: relative;
  overflow: hidden;
  padding: var(--space-8) 0 calc(var(--space-8) + 56px);
  border-bottom: 1px solid var(--color-line);
  background: linear-gradient(180deg, var(--color-brand-tint), var(--color-bg));
}

.hero::before {
  content: '';
  position: absolute;
  top: -140px;
  right: -100px;
  width: 460px;
  height: 460px;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(6, 182, 212, 0.2), rgba(6, 182, 212, 0));
}

.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: var(--space-7);
  align-items: center;
}

.hero-copy h1 {
  font-size: 44px;
}

.hero-copy .lede {
  max-width: 480px;
  margin-top: var(--space-4);
}

.hero-actions {
  display: flex;
  gap: var(--space-3);
  margin-top: var(--space-5);
}

.stats-overlap {
  position: relative;
  z-index: 1;
  margin-top: -56px;
}

.feature {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: var(--space-6);
  align-items: center;
  overflow: hidden;
}

.feature-art {
  height: 260px;
  background: linear-gradient(135deg, #0ea5e9, #6366f1);
}

.feature-copy {
  padding: var(--space-5) var(--space-5) var(--space-5) 0;
}

.feature-copy h3 {
  font-size: 22px;
}

.feature-copy .price {
  margin: var(--space-3) 0 var(--space-4);
}

.newsletter {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-6);
  align-items: center;
  padding: var(--space-6);
}

.form-note {
  margin-top: var(--space-2);
  font-size: 13px;
}

/* Products */

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-5);
}

.chip {
  padding: 6px 14px;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-pill);
  background: var(--color-surface);
  font-size: 14px;
  font-weight: 600;
  color: var(--color-muted);
}

.chip.is-active {
  border-color: var(--color-ink);
  background: var(--color-ink);
  color: #ffffff;
}

.thumb-1 {
  background: linear-gradient(135deg, #0ea5e9, #6366f1);
}

.thumb-2 {
  background: linear-gradient(135deg, #f59e0b, #ef4444);
}

.thumb-3 {
  background: linear-gradient(135deg, #10b981, #0e7490);
}

.thumb-4 {
  background: linear-gradient(135deg, #a855f7, #ec4899);
}

.thumb-5 {
  background: linear-gradient(135deg, #64748b, #0f172a);
}

.thumb-6 {
  background: linear-gradient(135deg, #facc15, #84cc16);
}

.bundles {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-5);
}

/* Pricing */

.plans {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-5);
  align-items: start;
  padding-top: var(--space-4);
}

.plan {
  position: relative;
  padding: var(--space-5);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  background: var(--color-surface);
}

.plan-featured {
  border: 2px solid var(--color-brand);
  box-shadow: var(--shadow-md);
}

.plan-ribbon {
  position: absolute;
  top: -13px;
  left: 50%;
  z-index: 1;
  padding: 3px 12px;
  border-radius: var(--radius-pill);
  background: var(--color-brand);
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  transform: translateX(-50%);
}

.plan-price {
  margin: var(--space-3) 0;
  font-size: 40px;
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.plan-price small {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0;
  color: var(--color-muted);
}

.plan-features {
  margin: var(--space-4) 0 var(--space-5);
}

.plan-features li {
  padding: var(--space-2) 0;
  border-top: 1px solid var(--color-line);
  font-size: 15px;
}

.plan .btn {
  width: 100%;
}

.faq {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-5);
}

.faq-item h3 {
  margin-bottom: var(--space-2);
}

.faq-item p {
  font-size: 15px;
  color: var(--color-muted);
}

/* Orders */

.table-tools {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: var(--space-4);
  font-size: 14px;
  color: var(--color-muted);
}

.pager {
  display: flex;
  gap: var(--space-2);
}

/* Contact */

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: var(--space-6);
  align-items: start;
}

.info-list dt {
  margin-top: var(--space-4);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--color-muted);
}

.info-list dt:first-child {
  margin-top: 0;
}

.info-list dd {
  overflow-wrap: anywhere;
}

/* About */

.story {
  display: grid;
  grid-template-columns: 1fr 480px;
  gap: var(--space-7);
  align-items: center;
}

.story p + p {
  margin-top: var(--space-4);
}

.story-art {
  border-radius: var(--radius-lg);
}

.avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: var(--space-3);
  border-radius: 50%;
  background: var(--color-brand-tint);
  font-size: 18px;
  font-weight: 800;
  color: var(--color-brand-dark);
}

.timeline {
  padding-left: var(--space-5);
  border-left: 2px solid var(--color-line);
}

.timeline-item {
  position: relative;
  padding-bottom: var(--space-5);
}

.timeline-item:last-child {
  padding-bottom: 0;
}

.timeline-item::before {
  content: '';
  position: absolute;
  top: 5px;
  left: -32px;
  width: 12px;
  height: 12px;
  border: 2px solid var(--color-surface);
  border-radius: 50%;
  background: var(--color-brand);
}

.timeline-year {
  font-weight: 800;
  color: var(--color-brand);
}

.cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  padding: var(--space-6);
  border-radius: var(--radius-lg);
  background: var(--color-ink);
  color: #ffffff;
}

.cta p {
  margin-top: var(--space-1);
  color: #c9d1d9;
}

@media (max-width: 720px) {
  .hero {
    padding-top: var(--space-7);
  }

  .hero-inner,
  .feature,
  .newsletter,
  .bundles,
  .plans,
  .faq,
  .contact-grid,
  .story {
    grid-template-columns: 1fr;
  }

  .hero-copy h1 {
    font-size: 32px;
  }

  .feature-copy {
    padding: 0 var(--space-5) var(--space-5);
  }

  .feature-art {
    height: 160px;
  }

  .newsletter {
    padding: var(--space-5);
  }

  .cta {
    flex-direction: column;
    align-items: flex-start;
  }
}
===TOKENS===
/* Design tokens and the web font. Every other stylesheet uses these. */

@font-face {
  font-family: 'Acme Sans';
  src: url('../fonts/acme-sans.woff2') format('woff2');
  font-weight: 300 900;
  font-style: normal;
  font-display: swap;
}

:root {
  --color-ink: #1f2328;
  --color-muted: #59636e;
  --color-line: #d8dee4;
  --color-bg: #f6f8fa;
  --color-surface: #ffffff;
  --color-brand: #0e7490;
  --color-brand-dark: #155e75;
  --color-brand-tint: #ecfeff;
  --color-success: #1a7f37;
  --color-success-tint: #e8f6ee;
  --color-danger: #cf222e;
  --color-danger-tint: #fdecea;
  --color-warning: #9a6700;
  --color-warning-tint: #fff8c5;

  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 64px;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-pill: 999px;

  --shadow-sm: 0 1px 2px rgba(31, 35, 40, 0.08);
  --shadow-md: 0 8px 24px rgba(31, 35, 40, 0.12);

  --font-sans: 'Acme Sans', system-ui, sans-serif;
  --content-width: 1040px;
  --header-height: 64px;
}
===BASE===
/* Reset, typography and page layout. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-ink);
  background: var(--color-bg);
}

h1,
h2,
h3,
p,
ul,
ol,
dl,
dd,
figure {
  margin: 0;
}

ul,
ol {
  padding: 0;
  list-style: none;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: var(--color-brand);
}

[hidden] {
  display: none !important;
}

h1 {
  font-size: 36px;
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: -0.02em;
}

h2 {
  font-size: 24px;
  line-height: 1.25;
  font-weight: 700;
  letter-spacing: -0.01em;
}

h3 {
  font-size: 17px;
  line-height: 1.3;
  font-weight: 700;
}

.container {
  width: 100%;
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 0 var(--space-5);
}

.section {
  padding: var(--space-7) 0 0;
}

.section-title {
  margin-bottom: var(--space-5);
